package org.sleepwell.app;
import java.time.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public final class SunriseAlarmTest {
    final ZoneId zone=ZoneId.of("America/New_York");final LocalDate date=LocalDate.of(2026,10,23);final SunriseSchedule solar=new SunriseSchedule(40.72,-74.02,15,true);
    Alarm alarm(){Alarm a=new Alarm(1);a.enabled=true;a.hour=6;a.minute=30;a.smartWindow=30;a.solar=solar;a.days.add(5);return a;}
    @Test public void actualAlarmNextAndDeliveryUseSunriseInsteadOfFallbackClock(){Alarm a=alarm();long at=solar.on(date,6,30,zone).at,now=date.atStartOfDay(zone).toInstant().toEpochMilli();assertEquals(at,a.next(now,zone));assertTrue(AlarmSkips.eligible(a,at,at-1800000,0,zone));assertFalse(AlarmSkips.eligible(a,at,at-1800001,0,zone));assertFalse(AlarmSkips.eligible(a,at,at,at,zone));long fallback=AlarmDate.at(date,6,30,zone);assertNotEquals(fallback,at);assertFalse(a.occurs(fallback,zone));assertFalse(AlarmSkips.eligible(a,fallback,fallback,0,zone));}
    @Test public void explicitSolarDateAndPolarClockFallbackEachHaveOnlyOneOccurrence(){Alarm a=alarm();a.days.clear();a.date=date;long at=a.next(date.atStartOfDay(zone).toInstant().toEpochMilli(),zone);assertEquals(0,a.next(at,zone));assertTrue(a.occurs(at,zone));a.solar=new SunriseSchedule(90,0,0,true);long fallback=AlarmDate.at(date,6,30,zone);assertEquals(fallback,a.next(fallback-1,zone));assertEquals(0,a.next(fallback,zone));assertTrue(a.occurs(fallback,zone));assertFalse(a.occurs(at,zone));}
    @Test public void malformedSolarFailsClosedAndConfigEditChangesScheduleOwnership(){Alarm a=alarm();String key=AlarmSkips.scheduleKey(a);a.solar=new SunriseSchedule(40.72,-74.02,-15,true);assertNotEquals(key,AlarmSkips.scheduleKey(a));a.solarInvalid=true;long at=solar.on(date,6,30,zone).at;assertEquals(0,a.next(at-60000,zone));assertFalse(a.occurs(at,zone));assertFalse(AlarmSkips.eligible(a,at,at,0,zone));}
    @Test public void absentSolarKeepsLegacyTimeAndKeyExactly(){Alarm a=alarm();a.solar=null;assertEquals("06:30",a.time());assertEquals("6:30:[5]:true:",AlarmSkips.scheduleKey(a));long fallback=AlarmDate.at(date,6,30,zone);assertEquals(fallback,a.next(fallback-1,zone));}
}
